<script setup>
import { Bike, BookOpenCheck, CheckCircle2, CircleOff, Clock3, Radio, Users, Waypoints } from '@lucide/vue';
import { computed, onMounted, ref } from 'vue';
import { useSocketListeners } from '../../composables/useSocket.js';
import { api } from '../../services/api.js';

const stats = ref(null); const loading = ref(true);
const cards = computed(() => stats.value ? [
  { label: 'Commuters', value: stats.value.totalCommuters, icon: Users, tone: 'green' },
  { label: 'Registered drivers', value: stats.value.totalDrivers, icon: Bike, tone: 'blue' },
  { label: 'Drivers online', value: stats.value.onlineDrivers, icon: Radio, tone: 'green' },
  { label: 'Available drivers', value: stats.value.availableDrivers, icon: Waypoints, tone: 'cyan' },
  { label: 'Waiting bookings', value: stats.value.waitingBookings, icon: Clock3, tone: 'amber' },
  { label: 'Active rides', value: stats.value.activeRides, icon: BookOpenCheck, tone: 'blue' },
  { label: 'Completed', value: stats.value.completedBookings, icon: CheckCircle2, tone: 'green' },
  { label: 'Cancelled', value: stats.value.cancelledBookings, icon: CircleOff, tone: 'red' },
] : []);
async function load() { try { const response = await api.get('/admin/dashboard'); stats.value = response.data.data; } finally { loading.value = false; } }
onMounted(load); useSocketListeners({ 'admin:booking_updated': load });
</script>
<template><section class="page admin-page"><div class="page-header"><div><span class="eyebrow">Operations center</span><h1 class="page-title">Dashboard</h1><p class="muted">Live overview of the RYDORA network.</p></div><span class="live"><i></i> Live data</span></div><div v-if="loading" class="stats-grid"><div v-for="n in 8" :key="n" class="skeleton stat-loading"></div></div><div v-else class="stats-grid"><article v-for="card in cards" :key="card.label" class="stat-card card"><span :class="['stat-icon', card.tone]"><component :is="card.icon" :size="21" /></span><div><small>{{ card.label }}</small><strong>{{ card.value }}</strong></div></article></div><div class="operations"><article class="card"><span class="eyebrow">Booking health</span><h2>Current demand</h2><div class="health-row"><span>Waiting for drivers</span><strong>{{ stats?.waitingBookings ?? 0 }}</strong></div><div class="health-row"><span>Active passenger rides</span><strong>{{ stats?.activeRides ?? 0 }}</strong></div><RouterLink to="/admin/bookings">Review all bookings →</RouterLink></article><article class="card"><span class="eyebrow">Driver network</span><h2>Availability</h2><div class="availability"><div class="ring"><strong>{{ stats?.onlineDrivers ? Math.round((stats.availableDrivers / stats.onlineDrivers) * 100) : 0 }}%</strong><span>available</span></div><p><strong>{{ stats?.availableDrivers ?? 0 }}</strong> of {{ stats?.onlineDrivers ?? 0 }} online drivers can accept a new ride.</p></div><RouterLink to="/admin/drivers">Manage drivers →</RouterLink></article></div></section></template>
<style scoped>.admin-page{max-width:1200px}.live{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border-radius:999px;background:#ecfdf5;color:var(--color-primary-dark);font-size:.7rem;font-weight:800}.live i{width:8px;height:8px;border-radius:50%;background:var(--color-accent);box-shadow:0 0 0 4px rgb(16 185 129/.15)}.stats-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.stat-loading{height:105px}.stat-card{display:flex;min-width:0;align-items:center;gap:13px;padding:15px}.stat-icon{display:grid;width:44px;height:44px;flex:0 0 auto;place-items:center;border-radius:13px}.stat-icon.green{color:#047857;background:#d1fae5}.stat-icon.blue{color:#1d4ed8;background:#dbeafe}.stat-icon.cyan{color:#0e7490;background:#cffafe}.stat-icon.amber{color:#a16207;background:#fef3c7}.stat-icon.red{color:#b91c1c;background:#fee2e2}.stat-card div{display:grid;gap:4px}.stat-card small{color:var(--color-text-soft);font-size:.66rem}.stat-card strong{font-size:1.35rem}.operations{display:grid;gap:15px;margin-top:18px}.operations article{padding:19px}.operations h2{font-size:1rem}.health-row{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--color-border);font-size:.78rem}.operations a{display:block;margin-top:15px;color:var(--color-primary-dark);font-size:.75rem;font-weight:800}.availability{display:flex;align-items:center;gap:18px}.ring{display:grid;width:95px;height:95px;flex:0 0 auto;place-items:center;align-content:center;border:10px solid #a7f3d0;border-radius:50%}.ring strong{font-size:1.05rem}.ring span{color:var(--color-text-soft);font-size:.58rem}.availability p{color:var(--color-text-soft);font-size:.76rem;line-height:1.55}.availability p strong{color:var(--color-text);font-size:1rem}@media(min-width:700px){.stats-grid{grid-template-columns:repeat(4,1fr)}.operations{grid-template-columns:1fr 1fr}} </style>

